css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .formar-fila{display: flex; align-items: center; gap: 8px; font-size: 17px; font-weight: 700; margin-bottom: 8px; flex-wrap: wrap;}
.mz .formar-fila .pieza{border: 1.5px solid var(--bosque); border-radius: 6px; padding: 4px 9px;}
.mz .formar-fila .mas{font-family: sans-serif;}
.mz .formar-fila .igual{font-size: 19px;}
.mz .formar-fila .caja-res{width: 95px; height: 38px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .cdu-tabla{border-collapse: collapse; margin-bottom: 4px;}
.mz .cdu-tabla th,.mz .cdu-tabla td{border: 1.5px solid var(--bosque); text-align: center;}
.mz .cdu-tabla th{font-family: sans-serif; font-size: 12px; background: #f3f3f3; padding: 3px 0; width: 60px;}
.mz .cdu-tabla .num-cab{width: 120px; background: #fff;}
.mz .cdu-tabla td{height: 32px; font-size: 19px; font-weight: 700;}
.mz .cdu-tabla td.cdu-d{background: #f3f3f3;}
.mz .serie-cajas{display: flex; gap: 6px; flex-wrap: wrap; font-size: 16px; font-weight: 700;}
.mz .serie-cajas .caja-num{width: 54px; height: 40px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
.mz .vf-fila{display: flex; align-items: center; gap: 12px; font-size: 14.5px; font-weight: 600; margin-bottom: 9px;}
.mz .vf-fila .frase{flex: 1; line-height: 1.3;}
.mz .vf-opts{display: flex; gap: 10px; flex-shrink: 0;}
.mz .vf-opts .vf{width: 30px; height: 30px; border: 1.5px solid var(--bosque); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 15px;}
